using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolvable.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (info) =>
        {
            // Reject everything except string
            if (info.Type != typeof(string))
                throw new NotSupportedException();
        }}
    }
};

bool found = restrictedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"\nTryGetTypeInfo(Person) on restricted options => found: {found}, info: {probed?.Type.Name ?? "(null)"}");

found = restrictedOptions.TryGetTypeInfo(typeof(string), out probed);
Console.WriteLine($"TryGetTypeInfo(string) on restricted options => found: {found}, info: {probed?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

